#!/usr/bin/env python3
"""
Adds the practitioner side of referrals.

Ten new files, two small edits. Nothing existing is rewritten, so this cannot
disturb the app you just shipped.

  new   src/lib/therapists.ts                      registration types, the gate, the rules
        src/lib/admin.ts                           who may verify (ADMIN_EMAILS, not a DB column)
        src/app/therapists/page.tsx                public landing for practitioners
        src/app/therapists/apply/page.tsx          the application
        src/app/therapists/dashboard/page.tsx      their status and listing
        src/app/admin/therapists/page.tsx          your verification queue
        src/components/therapist-apply-form.tsx
        src/components/admin-therapist-queue.tsx
        src/app/api/therapists/apply/route.ts
        src/app/api/admin/therapists/route.ts

  edit  src/lib/supabase/middleware.ts   protect /therapists/apply, /dashboard, /admin
        src/lib/supabase/admin.ts        comment: a third legitimate service-role caller
        .env.example                     ADMIN_EMAILS

The database side is already live -- the tables, the row-level security and the
trigger that stops a practitioner verifying themselves were applied directly.

Run from anywhere:  python3 add-therapists.py
"""

import base64
import json
import sys
from pathlib import Path

MIDDLEWARE_OLD = '''  "/science-check",
  "/onboarding",
];'''

MIDDLEWARE_NEW = '''  "/science-check",
  "/onboarding",
  // /therapists itself stays public -- practitioners have to be able to read
  // what they are signing up to before they sign in.
  "/therapists/apply",
  "/therapists/dashboard",
  "/admin",
];'''

ADMIN_COMMENT_OLD = """ * Service-role client. It bypasses row-level security entirely, so it is used
 * in exactly two places, both of which have no user session to act as:
 *   - deleting an auth user after their rows have gone
 *   - the RevenueCat webhook, called by their servers rather than a browser"""

ADMIN_COMMENT_NEW = """ * Service-role client. It bypasses row-level security entirely, so it is used
 * only where there is no user session to act as, or where the database is
 * deliberately refusing the signed-in user:
 *   - deleting an auth user after their rows have gone
 *   - the RevenueCat webhook, called by their servers rather than a browser
 *   - practitioner verification, whose whole point is that a practitioner
 *     cannot do it themselves; every caller there passes requireAdmin() first"""

ENV_BLOCK = """
# --- Admin -----------------------------------------------------------------
# Comma-separated emails allowed to verify practitioners at /admin/therapists.
# Deliberately not a database column: a boolean in the database is one bad
# policy away from someone approving themselves, and practitioner verification
# is the thing the whole referral safety story rests on.
ADMIN_EMAILS=
"""

BLOB = '{"src/lib/therapists.ts": "", "src/lib/admin.ts": "", "src/app/api/therapists/apply/route.ts": "", "src/app/api/admin/therapists/route.ts": "", "src/app/therapists/page.tsx": "", "src/app/therapists/apply/page.tsx": "", "src/app/therapists/dashboard/page.tsx": "", "src/app/admin/therapists/page.tsx": "", "src/components/therapist-apply-form.tsx": "", "src/components/admin-therapist-queue.tsx": ""}'

FILES = json.loads(BLOB)


def find_repo() -> Path:
    seeds = [Path(__file__).resolve().parent, Path.cwd()]
    for seed in seeds:
        for root in [seed, *seed.parents]:
            if (root / "src" / "lib" / "supabase" / "middleware.ts").is_file():
                return root
    sys.exit(
        "Could not find the repo above this script.\n"
        "Put this file inside ~/Documents/mentara-v2 and run it again."
    )


def main() -> None:
    root = find_repo()

    for rel, encoded in sorted(FILES.items()):
        path = root / rel
        path.parent.mkdir(parents=True, exist_ok=True)
        existed = path.is_file()
        path.write_bytes(base64.b64decode(encoded))
        print(f"  {'~' if existed else '+'} {rel}")

    mw = root / "src" / "lib" / "supabase" / "middleware.ts"
    text = mw.read_text(encoding="utf-8")
    if '"/therapists/apply"' in text:
        print("  = middleware (already done)")
    elif MIDDLEWARE_OLD in text:
        mw.write_text(text.replace(MIDDLEWARE_OLD, MIDDLEWARE_NEW, 1), encoding="utf-8")
        print("  ~ src/lib/supabase/middleware.ts")
    else:
        print("  ! middleware: could not find the protected-route list.")
        print("    Add \"/therapists/apply\", \"/therapists/dashboard\" and \"/admin\" by hand.")

    admin = root / "src" / "lib" / "supabase" / "admin.ts"
    text = admin.read_text(encoding="utf-8")
    if ADMIN_COMMENT_OLD in text:
        admin.write_text(text.replace(ADMIN_COMMENT_OLD, ADMIN_COMMENT_NEW, 1), encoding="utf-8")
        print("  ~ src/lib/supabase/admin.ts (comment)")

    env = root / ".env.example"
    if env.is_file():
        text = env.read_text(encoding="utf-8")
        if "ADMIN_EMAILS" not in text:
            env.write_text(text.rstrip("\n") + "\n" + ENV_BLOCK, encoding="utf-8")
            print("  ~ .env.example")

    print("\nBefore this works you need ADMIN_EMAILS set to your own email,")
    print("in .env.local and in Vercel (Production and Preview).")
    print("\nThen:")
    print('  git add -A && git commit -m "Practitioner registration and verification"')
    print("  git push")


if __name__ == "__main__":
    main()
